"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { listConnections } from "@/lib/api";
import { isLoggedIn } from "@/lib/auth";
import AppHeader from "@/components/AppHeader";
import Magnetic from "@/components/Magnetic";
import InteractiveCanvas from "@/components/InteractiveCanvas";

type Connection = {
  id: number;
  nickname: string;
  engine_type: string;
  host: string;
  database_name: string;
};

export default function HomePage() {
  const [connections, setConnections] = useState<Connection[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const router = useRouter();

  useEffect(() => {
    if (!isLoggedIn()) {
      router.push("/login");
      return;
    }
    listConnections()
      .then(setConnections)
      .finally(() => setLoading(false));
  }, [router]);

  const filteredConnections = connections.filter(
    (c) =>
      c.nickname.toLowerCase().includes(search.toLowerCase()) ||
      c.database_name.toLowerCase().includes(search.toLowerCase()) ||
      c.host.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <main className="relative min-h-screen bg-[#18181b] text-[#f3f4f6] selection:bg-[#3dd17e]/30 selection:text-[#3dd17e] overflow-x-hidden">
      <InteractiveCanvas />
      <AppHeader />

      <div className="relative z-10 mx-auto max-w-6xl px-6 py-12">
        {/* Header Hero Banner */}
        <div className="mb-10 flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <div className="mb-2 flex items-center gap-2">
              <span className="h-2.5 w-2.5 rounded-full bg-[#3dd17e] animate-pulse" />
              <span className="font-mono text-xs uppercase tracking-[0.2em] text-[#3dd17e] font-semibold">
                Database Dashboard
              </span>
            </div>
            <h1 className="font-display text-4xl font-extrabold text-white sm:text-5xl tracking-tight">
              Your Databases
            </h1>
            <p className="mt-2 text-sm text-[#94a3b8] max-w-lg leading-relaxed">
              Manage your live PostgreSQL and MySQL database connections or launch natural language SQL queries.
            </p>
          </div>

          <div className="flex items-center gap-3">
            <Magnetic strength={24}>
              <Link
                href="/connect"
                className="group inline-flex items-center gap-2 rounded-2xl bg-[#f0533d] px-6 py-3.5 font-display text-sm font-bold text-white shadow-[0_10px_30px_-8px_rgba(240,83,61,0.5)] transition-all duration-200 hover:bg-[#d94430] hover:scale-[1.02] active:scale-95"
              >
                <span className="text-lg font-light leading-none">＋</span>
                Connect Database
              </Link>
            </Magnetic>
          </div>
        </div>

        {/* Dashboard Metrics Bar */}
        <div className="mb-8 grid grid-cols-1 gap-4 sm:grid-cols-3">
          <div className="rounded-2xl border border-white/10 bg-[#242429]/80 p-5 backdrop-blur-xl transition hover:border-white/20">
            <p className="font-mono text-xs uppercase tracking-wider text-[#94a3b8]">Active Connections</p>
            <p className="mt-2 font-display text-3xl font-bold text-white">
              {loading ? "..." : connections.length}
            </p>
          </div>

          <div className="rounded-2xl border border-white/10 bg-[#242429]/80 p-5 backdrop-blur-xl transition hover:border-white/20">
            <p className="font-mono text-xs uppercase tracking-wider text-[#94a3b8]">Security Guardrail</p>
            <p className="mt-2 font-display text-2xl font-bold text-[#3dd17e] flex items-center gap-2">
              <span className="h-2.5 w-2.5 rounded-full bg-[#3dd17e]" />
              sqlglot AST
            </p>
          </div>

          <div className="rounded-2xl border border-white/10 bg-[#242429]/80 p-5 backdrop-blur-xl transition hover:border-white/20">
            <p className="font-mono text-xs uppercase tracking-wider text-[#94a3b8]">RAG Schema Retrieval</p>
            <p className="mt-2 font-display text-2xl font-bold text-[#f0533d]">
              Top 5 Tables
            </p>
          </div>
        </div>

        {/* Search Input Bar */}
        {connections.length > 0 && (
          <div className="mb-6">
            <input
              type="text"
              placeholder="Search by nickname, host, or database name..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full rounded-2xl border border-white/10 bg-[#121215]/80 px-5 py-3.5 text-sm text-white placeholder:text-[#94a3b8]/60 transition-all focus:border-[#3dd17e] focus:outline-none focus:ring-4 focus:ring-[#3dd17e]/20"
            />
          </div>
        )}

        {/* Content Section */}
        {loading ? (
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((i) => (
              <div
                key={i}
                className="h-44 rounded-3xl border border-white/10 bg-[#242429]/40 animate-pulse"
              />
            ))}
          </div>
        ) : filteredConnections.length === 0 ? (
          <div className="flex flex-col items-center justify-center gap-5 rounded-3xl border border-dashed border-white/15 bg-[#242429]/60 px-8 py-20 text-center backdrop-blur-xl transition hover:border-[#3dd17e]/40">
            <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-white/5 border border-white/10 text-2xl text-[#3dd17e]">
              ⛁
            </div>

            <div className="max-w-md">
              <h3 className="font-display text-2xl font-bold text-white">No databases connected yet</h3>
              <p className="mt-2 text-sm text-[#94a3b8] leading-relaxed">
                Connect your first PostgreSQL or MySQL database. Credentials are Fernet-encrypted at rest and all queries pass sqlglot SELECT-only validation.
              </p>
            </div>

            <Magnetic strength={20}>
              <Link
                href="/connect"
                className="mt-2 group inline-flex items-center gap-2 rounded-2xl bg-[#f0533d] px-6 py-3 font-display text-sm font-bold text-white shadow-[0_10px_25px_-6px_rgba(240,83,61,0.5)] transition-all hover:bg-[#d94430] active:scale-95"
              >
                Connect Now
                <span className="transition-transform group-hover:translate-x-1">→</span>
              </Link>
            </Magnetic>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {filteredConnections.map((conn) => (
              <Link
                key={conn.id}
                href={`/ask?connection_id=${conn.id}`}
                className="group relative block overflow-hidden rounded-3xl border border-white/10 bg-[#242429]/80 p-6 backdrop-blur-xl transition-all duration-300 hover:-translate-y-1 hover:border-[#3dd17e]/40 hover:shadow-[0_20px_50px_-15px_rgba(0,0,0,0.6)]"
              >
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <span className="inline-block font-mono text-[11px] font-semibold uppercase tracking-wider text-[#3dd17e]">
                      ID: #{conn.id}
                    </span>
                    <h4 className="font-display text-xl font-bold text-white group-hover:text-[#3dd17e] transition-colors">
                      {conn.nickname}
                    </h4>
                  </div>

                  <span className="rounded-full border border-white/10 bg-white/5 px-3 py-1 font-mono text-[10px] font-semibold uppercase tracking-wider text-[#94a3b8]">
                    {conn.engine_type}
                  </span>
                </div>

                <div className="mt-4 space-y-1 font-mono text-xs text-[#94a3b8]">
                  <p className="truncate"><span className="text-white/40">Host:</span> {conn.host}</p>
                  <p className="truncate"><span className="text-white/40">DB:</span> {conn.database_name}</p>
                </div>

                <div className="mt-6 flex items-center justify-between border-t border-white/10 pt-4 text-xs font-semibold text-[#3dd17e]">
                  <span className="flex items-center gap-1.5 text-[#94a3b8] group-hover:text-white transition-colors">
                    <span className="h-1.5 w-1.5 rounded-full bg-[#3dd17e]" />
                    Ready to query
                  </span>
                  <span className="transition-transform group-hover:translate-x-1">
                    Ask Question →
                  </span>
                </div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </main>
  );
}
